INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('plague','n.祸患，瘟疫，灾害','/pleɪɡ/','/pleɪɡ/','noun',["Ten Biblical plagues over Egypt, ranging from locusts to the death of the crown prince, finally forced Pharaoh to let Moses''s people go.","Bart is an utter plague; his pranks never cease.","Natural catastrophes plagued the colonists till they abandoned the pestilent marshland."]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('retrospect','n.回顾，反顾','/ˈɹɛtɹoˌspɛkt/','/ˈɹɛtɹoˌspɛkt/','noun',["1800: Alexander Hamilton, Letter from Alexander Hamilton, Concerning the Public Conduct and Character of John Adams, Esq. President of the United States - To give a correct idea of the circumstances.., it may be useful to retrospect to an early period."]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('ban','n.禁止，禁令vt.禁止','/bæn/','/bæn/','noun',["Bans is common and ordinary amongst the Feudists, and signifies a proclamation, or any public notice.","France was at such a Pinch..that they call''d their Ban and Arriere Ban, the assembling whereof had been long discussed, and in a manner antiquated.","Bare feet are banned in this establishment."]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('canon','n.教规；正典，经典圣经；真作集','/ˈkæn.ən/','/ˈkæn.ən/','noun',["The trial must proceed according to the canons of law.","the entire Shakespeare canon","We must proceed according to canon law."]);
