INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fascinate','v.使着迷；使神魂颠倒','/ˈfæsɪneɪt/','/ˈfæsɪneɪt/','verb',["The flickering TV fascinated the cat.","We were fascinated by the potter''s skill.","Her gait fascinates all men."]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('diplomatic','adj.外交的，老练的；策略的，有手腕的','/ˌdɪpləˈmætɪk/','/ˌdɪpləˈmætɪk/','noun',["Albania immediately severed diplomatic relations with Zimbabwe.","Thoughtful corrections can be diplomatic as well as instructional.","Whereas a diplomatic edition uses as its base text a single, \"best\" manuscript, to which other textual evidence is collated and organized into an apparatus, a critical text of the LXX/OG [= Septuagint or Old Greek] may be described as a collection of the oldest recoverable texts, carefully restored book by book (or section by section), aiming at achieving the closest approximation to the original translations (from Hebrew or Aramaic) or compositions (in Greek), systematically reconstructed from the widest array of relevant textual data (including controlled conjecture).  The International Organization for Septuagint and Cognate Studies, Critical Editions of Septuagint/Old Greek Texts."]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('projector','n.投影仪','','','noun',[]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('importunate','adj.不断要求的，急切的','/ɪmˈpɔːtjʊnət/','/ɪmˈpɔːtjʊnət/','adjective',[]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('percipient','adj.感知的；有觉察力的','','','noun',["In the course of investigating the haunting, I interviewed several percipients.","Over time children advance from the percipient stage to the perceptive stage, in which they begin to reflect on the significance of events."]);
