INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('contact','n.接触','','','noun',["I haven''t been in contact with her for years.","Touch the contact to ground and read the number again.","The salesperson had a whole binder full of contacts for potential clients."]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('discharge','v.正式准许〔某人〕离开〔尤指让病人出院或让军人退伍等〕；通知〔病人〕出院；开除〔士兵〕军籍n.准许离开；出院；退伍','','','noun',["to discharge a prisoner","to discharge a cargo","A pipe discharges water."]);
