INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('advocate','n.提倡者，鼓吹者vt.提倡，鼓吹','/ˈæd.və.keɪt/','/ˈæd.və.keɪt/','noun',["Since she started working with her advocate, she has become much more confident.","I like trees, but I do not advocate living in them.","We have been advocating for changes in immigration law."]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('posthumous','adj.死后的','/ˈpɒs.tʃə.məs/','/ˈpɒs.tʃə.məs/','adjective',["Posthumous orphans never even knew their fathers.","Usage note: Posthumous awards are made when the intended recipient dies as a result of the action which merits the award. Even a short time lag between the action and the decision may cause the award to be conferred after death or there may be a longer delay such as when a review board decides to confer an award decades after a war has ended but such awards while they may be post mortem (literally, \"after death\") are not posthumous awards.","Artists obscure during their life often receive posthumous recognition, too late for them to enjoy."]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('frequency','n.频率','/ˈfɹiːkwənsi/','/ˈfɹiːkwənsi/','noun',["The frequency of bus service has been improved from one every 15 to one every 12 minutes.","The FAQ addresses questions that come up with some frequency.","Broadcasting live at a frequency of 98.3 megahertz, we’re your rock alternative!"]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('zero','n.零','/ˈzɪəɹəʊ/','/ˈzi(ˌ)ɹoʊ/','noun',["In unary and k-adic notation in general, zero is the empty string.","One million has six zeroes.","He knows zero about humour."]);
