INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('missile','n.导弹，发射物','/ˈmɪsaɪl/','/ˈmɪsaɪl/','noun',["The Rhodians, who used leaden bullets, were able to project their missiles twice as far as the Persian slingers, who used large stones.","That missile is explosive enough to kill hundreds."]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('dynamic','adj.动力的；动力学的；动态的','/daɪˈnæ.mɪk/','/daɪˈnæ.mɪk/','noun',["Watch the dynamic between the husband and wife when they disagree.","The study of fluid dynamics quantifies turbulent and laminar flows.","If you pay attention to the dynamics as you play, it''s a very moving piece."]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('sector','n.扇形','/ˈsɛk.təɹ/','/ˈsɛk.təɹ/','noun',["public sector;  private sector"]);
