INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('corrupt','v.贿赂，收买；使腐败，使败坏adj.腐败的，贪污的；被破坏的','/kəˈɹʌpt/','/kəˈɹʌpt/','verb',["to corrupt a book","The government here is corrupt, so we''ll emigrate to escape them.","It turned out that the program was corrupt - that''s why it wouldn''t open."]);
