INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assert','vt.断言；坚持；主张；维护','/əˈsɜːt/','/əˈsɝt/','noun',["He would often assert that there was life on other planets.","Salman Rushdie has asserted his right to be identified as the author of this work.","to assert our rights and liberties"]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('penchant','n.倾向；趣味；嗜好','/ˈpɒnʃɒn/','/ˈpɒnʃɒn/','noun',["He has a penchant for fine wine."]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('place','n.数','/pleɪs/','/pleɪs/','noun',["I''m in a strange place at the moment.","three decimal places;  the hundreds place","That''s what I said in the first place!"]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('irrational','adj.无理性的，失去理性的','/ɪˈɹæʃ.(ə.)nəl/','/ɪˈɹæʃ.(ə.)nəl/','noun',["an irrational decision","The number π is irrational."]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('glacial','adj.冰冷的；冰的，冰状的','/ˈɡleɪ.ʃ(ɪ)əl/','','noun',["Wang Shijin is a glacier expert and director of the Yulong Snow Mountain Glacial and Environmental Observation Research Station.","After the rain and frost, the pavements were glacial.","On cold days, glacial acetic acid will freeze in the bottle."]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('coddle','v.娇养，溺爱；悉心照料','/ˈkɒdəl/','/ˈkɒdəl/','noun',[]);
