INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('lead','n.导线','/lɛd/','/lɛd/','noun',["This copy has too much lead; I prefer less space between the lines.","They pumped him full of lead.","continuous firing leads the grooves of a rifle."]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('token','n.辅币','/ˈtəʊkən/','/ˈtoʊkən/','noun',["According to the Bible, the rainbow is a token of God''s covenant with Noah.","Please accept this bustier as a token of our time together.","A book token is the easiest option for a Christmas gift."]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('fraction','n.分数','/ˈfɹæk.ʃən/','/ˈfɹæk.ʃən/','noun',[]);
INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('filter','n.滤管','/ˈfɪltə/','/ˈfɪltɚ/','noun',["He runs an email filter to catch the junk mail.","He''s got no filter, and he''s always offending people as a result.","If (1) the universal set (here, the set of natural numbers) were called a \"large\" set, (2) the superset of any \"large\" set were also a \"large\" set, and (3) the intersection of a pair of \"large\" sets were also a \"large\" set, then the set of all \"large\" sets would form a filter."]);
