INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('expect','v.期待，预期，盼望，指望','/ɛkˈspɛkt/','/ɛkˈspɛkt/','verb',["He never expected to be discovered.","You are expected to get the task done by the end of next week."]);
