INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('assess','vt.估定；评定','/əˈsɛs/','/əˈsɛs/','verb',["He assessed the situation.","A $10.00 late fee will be assessed on all overdue accounts.","Once you''ve submitted a tax return, the Tax Department will assess the amount of tax you still owe."]);
