INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('apology','n.道歉，歉意，认错','/əˈpɒl.ə.dʒi/','/əˈpɒl.ə.dʒi/','noun',["The CEO made a public apology for the scandal, and promised full cooperation with the authorities.","The Apology of Socrates.","a poor apology for a hotel room"]);
