INSERT INTO SAT (word,translate,phonetic_uk,phonetic_us,part_of_speech,examples) VALUES ('divest','v.剥夺，脱去','/daɪˈvɛst/','/daɪˈvɛst/','verb',["When I wake up, I make a point to divest myself of all my prejudices, ready to start the day.","As Glasgow becomes the first university in Europe to divest from fossil fuels."]);
